import { Monitor, Moon, Sun } from '@phosphor-icons/react';
import { useTheme, type ThemeMode } from '@/components/Theme';

const { mode, setMode } = useTheme();

<ToggleGroup aria-label="Colour mode" size="sm" value={mode} onValueChange={(next) => setMode(next as ThemeMode)}>
  <ToggleGroup.Item value="system"><Monitor aria-hidden />System</ToggleGroup.Item>
  <ToggleGroup.Item value="light"><Sun aria-hidden />Light</ToggleGroup.Item>
  <ToggleGroup.Item value="dark"><Moon aria-hidden />Dark</ToggleGroup.Item>
</ToggleGroup>
